INSERT INTO "ci_kaizen_proposals" ("id","code","title","category","category_label","registration_type","sub_status","region","department","factory","proposer_name","proposer_emp_code","dept_code","before_description","after_solution","saved_seconds","before_image_url","after_image_url","attachments_json","status","award_title","score_points","avg_rating","rating_count","vote_count","view_count","rejection_reason","version","created_at","updated_at","required_reviewer_ids_json","average_score","evaluated_at","comments","review_comment","proposer_position","proposer_month","proposer_year","hr_suggestor","customer","product_group","product_code","quantity","pricing_direction","time_before_seconds","time_after_seconds","efficiency_value_vnd","legacy_code","team_code","plant_code","approval_status","evaluation_result","approved_by","approved_at","evaluated_by","review_status","is_archived","before_video_url","after_video_url","pair_quantity","line","total_savings_vnd","total_savings_words","trang_thai","source_region","site_code","external_id","plant_group","is_edited","so_giay_tiet_kiem","cost_before","cost_after") VALUES('ci_1790320653349_8hkw2','CI-2026-016','Tích hợp thông báo tự động qua Zalo Bot cho hệ thống Gemba.Pro','AUTOMATION','6.Tự động hoá','THI_DUA','CHO_DANH_GIA','Nhà Máy Miền Đông','Đầu Vào','Nhà Máy Miền Đông','Phạm Nguyễn Anh Huy','202608001','SK','Hệ thống Gemba.Pro hiện chưa có kênh thông báo tức thời cho người dùng khi có phiếu mới/cập nhật trạng thái. Người phụ trách phải tự đăng nhập web để kiểm tra, dẫn đến chậm trễ trong xử lý vấn đề, đặc biệt với các phiếu ưu tiên mức độ xử lí gấp dẫn đến lãng phí do không kịp thời đưa ra quyết định.',replace('1. Tích hợp Zalo Bot vào hệ thống Gemba.Pro để tự động gửi thông báo (phiếu mới, phân công, hoàn thành, nhắc xử lý) tới người dùng và nhóm Zalo liên quan. \n2. Thiết lập webhook nhận phản hồi từ Zalo và cơ chế chống trường hợp gửi trùng 1 vấn đề nhiều lần. Bổ sung công cụ kiểm tra cấu hình (ZALO_BOT_TOKEN, ZALO_GROUP_CHAT_ID) để dễ dàng chẩn đoán khi bot không gửi được tin nhắn, đảm bảo thông tin phiếu được truyền tải kịp thời theo thời gian thực, giảm thời gian chờ xử lý hoặc đến cuối ngày mới phát hiện vấn đề. \n3. Cuối ngày BOT sẽ tự tổng hợp và gửi thông báo về kết quả tổng các vấn đề được phát hiện – các vấn đề đã được xử lí – các vấn đề chưa được xử lí (thông tin gửi báo cáo sẽ được liệt kê vấn đề, chuyền, tổ và người chịu trách nhiệm thực thi đối với các vấn đề chưa được xử lí) trong quá trình đi GEMBA trong ngày giúp cho cán bộ quản lí từ cấp nhà máy – phân xưởng – tổ trưởng trực tiếp sản xuất đều nắm bắt được kết quả giúp cho nâng cao được năng lực cán bộ quản lí giải quyết hiện trường và ra quyết định. \n4. Giá trị mang lại \n- Tiết kiệm tiền mua Agent ngoài 600.000đ/tháng/app = 7.200.000đ/năm. \n- Tiết kiệm thời gian: phát hiện vấn đề sớm, ra quyết định khắc phục vấn đề, tránh lãng phí ( bình quân sẽ giúp tiết kiệm được khoảng 10 phút cho vấn đề phát hiện và giải quyết vấn đề sớm, trị giá 1 năm khoảng 93 600 phút giả định 100 tổ trưởng trong đó có 30% các tổ có vấn đề và phải giải quyết vấn đề). \n- Giải pháp này không chỉ áp dụng cho GEMBA có thể áp dụng bất kì phần mềm nào cần ưu tiên mức độ phát hiện vấn đề và giải quyết vấn đề theo thời gian thực.','\n',char(10)),0,'https://res.cloudinary.com/dwl2xtbqa/image/upload/v1790320642/wm2jpljruom2bhsvgk64.jpg','https://res.cloudinary.com/dwl2xtbqa/image/upload/v1790320740/vpchuoiskechers/sk_kaizen_after_1790320740189_msqo4_2aobor11ee4hi3rhzbaz.jpg?v=1790320740','[{"url":"https://res.cloudinary.com/dwl2xtbqa/image/upload/v1790320642/wm2jpljruom2bhsvgk64.jpg","tag":"BEFORE","type":"image"},{"url":"https://res.cloudinary.com/dwl2xtbqa/image/upload/v1790320740/vpchuoiskechers/sk_kaizen_after_1790320740189_msqo4_2aobor11ee4hi3rhzbaz.jpg?v=1790320740","tag":"AFTER","type":"image"}]','UNDER_REVIEW',NULL,92.75,0,0,0,59,NULL,1,'2026-09-25 07:17:33','2026-09-25 07:27:13','["TGĐ-001","PTGĐ-002","GĐ-003","PGĐ-004","202608001","MD-LEAD-01"]',92.75,NULL,NULL,'Đã phê duyệt tính khả thi (Bước 3)','Công nhân',9,2026,'','Skechers','','GEMBA',2,'TRI_GIA',0,0,0,NULL,NULL,'VP2_SKECHERS','PHE_DUYET','PENDING',NULL,NULL,NULL,'CHO_PHE_DUYET',0,NULL,NULL,2,'',89400000,'Tám mươi chín triệu bốn trăm nghìn đồng','CHO_DUYET','Văn phòng Chuỗi','vpchuoiskechers',NULL,'VPCHUOI',1,0,0,0);
