INSERT INTO "system_settings" ("key","value","updated_at") VALUES('landing_cms','{"hero":{"titlePrefix":"TBS GROUP","titleHighlight":"Công Ty Cổ Phần Thái Bình Kiên Giang","prefixConfig":{"text":"TBS GROUP","fontSize":36,"colorMode":"solid","color":"#ffffff","gradient":{"from":"#ffffff","to":"#2fd39a","direction":"to right"}},"highlightConfig":{"text":"Công Ty Cổ Phần Thái Bình Kiên Giang","fontSize":36,"colorMode":"gradient","color":"#2fd39a","gradient":{"from":"#2fd39a","to":"#fbbf24","direction":"to right"}},"quoteItalic":"“Excellence in Manufacturing. Excellence in Leadership.”","description":"Không gian điều hành đại diện cho năng lực quản trị, văn hóa doanh nghiệp và tiêu chuẩn vận hành của Tổ hợp Kiên Giang - TBS Group. Thiết kế hướng đến sự tinh gọn, hiện đại và chuyên nghiệp, phản ánh vị thế của một doanh nghiệp sản xuất trong chuỗi cung ứng toàn cầu.","bgImage":"https://res.cloudinary.com/dwl2xtbqa/image/upload/v1787832561/kvobf8bssycbijqwiq33.jpg","handsImage":"/images/tbs-hands.png","teamImage":"https://res.cloudinary.com/dwl2xtbqa/image/upload/v1787832565/bdypokzsyjlzxkbqnfhk.jpg","quoteBadgeText":"Chung sức kiến tạo tương lai","stat1Value":"10+","stat1Label":"Năm Kinh Nghiệm","stat2Value":"10M+","stat2Label":"Sản Phẩm / Năm","stat3Value":"5,000+","stat3Label":"Nhân Sự Vận Hành"},"workspace":{"headline":"Môi trường làm việc chuẩn Corporate","description":"Mỗi không gian được kiến tạo nhằm thúc đẩy hiệu suất, sự kết nối và tinh thần đổi mới. Đây là nơi đội ngũ cùng chia sẻ mục tiêu, nâng cao chất lượng và không ngừng hoàn thiện để mang đến những giá trị vượt kỳ vọng cho khách hàng và đối tác trên toàn cầu.","pillars":[{"title":"Chuẩn mực không gian","desc":"Thiết kế hiện đại, tối giản theo tiêu chuẩn corporate, tạo nên môi trường làm việc chuyên nghiệp, đồng bộ và hiệu quả."},{"title":"Hiệu quả vận hành","desc":"Không gian được quy hoạch khoa học, tối ưu kết nối giữa các phòng ban, hỗ trợ quy trình điều hành nhanh chóng và chính xác."},{"title":"Bản sắc thương hiệu","desc":"Hệ thống nhận diện được ứng dụng xuyên suốt, phản ánh giá trị thương hiệu TBS và vị thế của doanh nghiệp trong chuỗi cung ứng toàn cầu."},{"title":"Môi trường truyền cảm hứng","desc":"Không gian mở, tiện nghi và thân thiện, khuyến khích sự hợp tác, sáng tạo và phát triển bền vững của đội ngũ."}]},"workspaceDepartments":[{"id":"sanh","name":"Sảnh","icon":"building","order":1,"images":[{"id":"img-sanh-1","src":"https://res.cloudinary.com/dwl2xtbqa/image/upload/v1787832792/l0zssbvifygkbp2dvzhe.jpg","caption":"Không gian làm việc chuẩn mực","order":1},{"id":"img-sanh-2","src":"https://res.cloudinary.com/dwl2xtbqa/image/upload/v1787832796/qw2zlgbdnjq0f7q9jvjm.jpg","caption":"Khu làm việc phối hợp","order":2},{"id":"img-sanh-3","src":"https://res.cloudinary.com/dwl2xtbqa/image/upload/v1787832801/pidfdagojrhcb1cpyhhs.jpg","caption":"Điểm nhấn thiết kế nội thất","order":3}]},{"id":"nhamay1","name":"Văn phòng","icon":"briefcase","order":2,"images":[{"id":"img-nm1-1","src":"https://res.cloudinary.com/dwl2xtbqa/image/upload/v1787832834/tkybuy6nmq0ux3cwd2ib.jpg","caption":"Quy trình sản xuất giày SKECHERS","order":1},{"id":"img-nm1-2","src":"https://res.cloudinary.com/dwl2xtbqa/image/upload/v1787832838/pffvzmw64a54xybiim5g.jpg","caption":"Toàn cảnh xưởng may Nhà máy 1","order":2}]},{"id":"nhamay2","name":"Phòng Đào Tạo","icon":"users-round","order":3,"images":[{"id":"img-nm2-1","src":"https://res.cloudinary.com/dwl2xtbqa/image/upload/v1787832872/dyqcjystuliykzdzap2l.jpg","caption":"Khu xưởng gò Nhà máy 2","order":1},{"id":"img-nm2-2","src":"https://res.cloudinary.com/dwl2xtbqa/image/upload/v1787832881/p6gtim2dav6xnk9ilp7s.jpg","caption":"Băng chuyền sản xuất thể thao SKECHERS","order":2},{"id":"img-nm2-3","src":"https://res.cloudinary.com/dwl2xtbqa/image/upload/v1787832885/q4rlaqzuwc8txe006k8d.jpg","caption":"Khu vực sấy gò tự động","order":3},{"id":"img-nm2-4","src":"https://res.cloudinary.com/dwl2xtbqa/image/upload/v1787832889/coiybgokx8zpqhd6ttxi.jpg","caption":"Tổ kiểm định 100% sản phẩm","order":4}]},{"id":"nhamay3","name":"Nhà máy","icon":"factory","order":4,"images":[{"id":"img-nm3-1","src":"https://res.cloudinary.com/dwl2xtbqa/image/upload/v1787832908/ziwiepptsxptfwen4jq0.jpg","caption":"Tổ hợp xưởng may Nhà máy 3","order":1},{"id":"img-nm3-2","src":"https://res.cloudinary.com/dwl2xtbqa/image/upload/v1787832912/uj8wctldsnhu1to0lmeg.jpg","caption":"Chuyền sản xuất dòng sản phẩm Work Shoes","order":2},{"id":"img-nm3-3","src":"https://res.cloudinary.com/dwl2xtbqa/image/upload/v1787832915/pdiy481rxoc7tydckfkb.jpg","caption":"Thiết bị kiểm tra độ bền kéo đế","order":3},{"id":"img-nm3-4","src":"https://res.cloudinary.com/dwl2xtbqa/image/upload/v1787832919/vuuk9x3j3qchrk89xrbc.jpg","caption":"Hệ thống chiếu sáng tự nhiên nhà xưởng","order":4},{"id":"img-nm3-5","src":"https://res.cloudinary.com/dwl2xtbqa/image/upload/v1787832923/kaju30qfkulzqwxbspth.jpg","caption":"Khu vực phân loại bán thành phẩm","order":5},{"id":"img-nm3-6","src":"https://res.cloudinary.com/dwl2xtbqa/image/upload/v1787832928/bmlovo0xpbi824svfqbw.jpg","caption":"Tổ may tự động hóa","order":6}]}],"excellence":{"title":"Dấu Ấn Thương Hiệu & Đẳng Cấp Chuỗi Cung Ứng","description":"Tổ hợp Kiên Giang - TBS Group tuân thủ nghiêm ngặt các tiêu chuẩn chất lượng cao nhất của các đối tác chiến lược toàn cầu. Hệ thống áp dụng quy trình số hóa 100%, nâng cao năng suất và đảm bảo an toàn lao động.","image":"https://res.cloudinary.com/dwl2xtbqa/image/upload/v1787877867/yvstkoktfmibadvrs1yw.jpg","points":[{"title":"Vận Hành Chuẩn Hóa 4.0","desc":"Áp dụng hệ thống quản trị sản xuất số hóa (MES) và tự động hóa quy trình giúp kiểm soát thời gian thực."},{"title":"Cam Kết Bền Vững (ESG)","desc":"Sử dụng năng lượng mặt trời áp mái, giảm phát thải carbon và tuân thủ các chứng nhận an toàn hóa chất quốc tế."},{"title":"Phát Triển Con Người","desc":"Liên tục đào tạo nâng cao tay nghề cho hơn 5,000 cán bộ công nhân viên với môi trường nhân văn."}]},"products":{"title":"Sản