PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE departments (
  id TEXT PRIMARY KEY,
  num TEXT NOT NULL,
  name TEXT NOT NULL,
  sub TEXT NOT NULL,
  icon_name TEXT NOT NULL,
  has_data INTEGER DEFAULT 1,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE system_notifications (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  desc TEXT NOT NULL,
  dept_id TEXT,
  timestamp TEXT NOT NULL,
  unread INTEGER DEFAULT 1
);
CREATE TABLE qc_metrics (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  date TEXT NOT NULL,
  pass_rate REAL DEFAULT 98.6,
  defect_count INTEGER DEFAULT 14,
  gemba_issues INTEGER DEFAULT 3,
  oee REAL DEFAULT 91.5
);
CREATE TABLE production_metrics (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  date TEXT NOT NULL,
  monthly_output TEXT DEFAULT '586,000 Đôi',
  active_lines INTEGER DEFAULT 33,
  kaizen_proposals INTEGER DEFAULT 128,
  target_pct REAL DEFAULT 104.2
);
CREATE TABLE meeting_rooms (id TEXT PRIMARY KEY, name TEXT NOT NULL, capacity INTEGER DEFAULT 10, location TEXT NOT NULL, equipment TEXT, status TEXT DEFAULT 'AVAILABLE', is_locked INTEGER DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, room_code TEXT, managing_unit TEXT, images TEXT, floor INTEGER, sort_order INTEGER);
CREATE TABLE room_bookings (id TEXT PRIMARY KEY, room_id TEXT NOT NULL, room_name TEXT NOT NULL, title TEXT NOT NULL, booker_name TEXT NOT NULL, department TEXT NOT NULL, booking_date TEXT NOT NULL, time_slot TEXT NOT NULL, attendees_count INTEGER DEFAULT 5, notes TEXT, status TEXT DEFAULT 'CONFIRMED', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, version INTEGER DEFAULT 1, user_id TEXT, emp_code TEXT, user_name TEXT, purpose TEXT, participants_count INTEGER DEFAULT 1, rejection_reason TEXT, meeting_type TEXT DEFAULT 'OFFLINE', platform TEXT, meeting_link TEXT, meeting_credentials TEXT);
CREATE TABLE visitors (id TEXT PRIMARY KEY, badge_code TEXT NOT NULL UNIQUE, visitor_name TEXT NOT NULL, company TEXT NOT NULL, id_card TEXT, host_name TEXT NOT NULL, department TEXT NOT NULL, room_location TEXT NOT NULL, visit_date TEXT NOT NULL, expected_time TEXT NOT NULL, status TEXT DEFAULT 'EXPECTED', notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE business_trips (id TEXT PRIMARY KEY, code TEXT NOT NULL, title TEXT NOT NULL, region TEXT DEFAULT 'VP Chuỗi', factory TEXT, creator TEXT NOT NULL, department TEXT NOT NULL, location TEXT NOT NULL, start_date TEXT NOT NULL, end_date TEXT NOT NULL, days_count INTEGER DEFAULT 1, transport TEXT DEFAULT 'Xe công ty', participants_count INTEGER DEFAULT 1, purpose TEXT, address TEXT, proposal_text TEXT, participants_json TEXT, status TEXT DEFAULT 'PENDING', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, estimated_cost REAL DEFAULT 0.0, approved_level TEXT, l1_approved_by TEXT, l1_approved_at DATETIME, l2_approved_by TEXT, l2_approved_at DATETIME, rejection_reason TEXT, version INTEGER DEFAULT 1, attachments_json TEXT, invoices_json TEXT, creator_emp_code TEXT, rejected_level TEXT, budget_status TEXT DEFAULT 'pending_dept_budget', budget_amount REAL DEFAULT 0, budget_rejection_reason TEXT, legacy_code TEXT, department_id TEXT, destinations_json TEXT, logistics_json TEXT, logistics_status TEXT DEFAULT 'NOT_STARTED');
CREATE TABLE roles (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL UNIQUE,
    code TEXT NOT NULL UNIQUE,
    level INTEGER NOT NULL DEFAULT 4,
    department_id INTEGER,
    description TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (department_id) REFERENCES departments(id) ON DELETE SET NULL
);
CREATE TABLE permissions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    code TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL,
    module TEXT NOT NULL,
    action TEXT NOT NULL
);
CREATE TABLE role_permissions (
    role_id INTEGER NOT NULL,
    permission_id INTEGER NOT NULL,
    PRIMARY KEY (role_id, permission_id),
    FOREIGN KEY (role_id) REFERENCES roles(id) ON DELETE CASCADE,
    FOREIGN KEY (permission_id) REFERENCES permissions(id) ON DELETE CASCADE
);
CREATE TABLE branches (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL UNIQUE,
    region TEXT NOT NULL,
    address TEXT
);
CREATE TABLE sectors (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL UNIQUE,
    code TEXT NOT NULL UNIQUE
);
CREATE TABLE zones (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    code TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL,
    description TEXT
);
CREATE TABLE lines (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    zone_id INTEGER NOT NULL,
    code TEXT NOT NULL,
    name TEXT NOT NULL,
    FOREIGN KEY (zone_id) REFERENCES zones(id) ON DELETE CASCADE
);
CREATE TABLE machines (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    machine_code TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL,
    serial_number TEXT,
    zone_id INTEGER,
    line_id INTEGER,
    branch_id INTEGER,
    status TEXT DEFAULT 'OPERATING', -- OPERATING, WARNING, DOWN, MAINTENANCE
    install_date TEXT,
    specs TEXT,
    qr_code_data TEXT UNIQUE,
    grid_x INTEGER DEFAULT 0,
    grid_y INTEGER DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (zone_id) REFERENCES zones(id) ON DELETE SET NULL,
    FOREIGN KEY (line_id) REFERENCES lines(id) ON DELETE SET NULL,
    FOREIGN KEY (branch_id) REFERENCES branches(id) ON DELETE SET NULL
);
CREATE TABLE incident_categories (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    code TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL,
    default_priority TEXT DEFAULT 'MEDIUM', -- LOW, MEDIUM, HIGH, CRITICAL
    estimated_fix_time_mins INTEGER DEFAULT 30
);
CREATE TABLE maintenance_tickets (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    ticket_code TEXT NOT NULL UNIQUE,
    machine_id INTEGER NOT NULL,
    reported_by_id INTEGER NOT NULL,
    assigned_to_id INTEGER,
    category_id INTEGER,
    branch_id INTEGER,
    priority TEXT DEFAULT 'MEDIUM',
    status TEXT DEFAULT 'OPEN', -- OPEN, ASSIGNED, IN_PROGRESS, RESOLVED, CLOSED
    description TEXT,
    image_url TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    accepted_at DATETIME,
    started_at DATETIME,
    completed_at DATETIME,
    response_time_sec INTEGER DEFAULT 0,
    resolution_time_sec INTEGER DEFAULT 0,
    total_downtime_sec INTEGER DEFAULT 0,
    root_cause TEXT,
    resolution_notes TEXT,
    spare_parts_used TEXT,
    estimated_repair_cost REAL DEFAULT 0.0,
    approval_status TEXT DEFAULT 'APPROVED', created_by TEXT, assigned_to TEXT, resolved_note TEXT, resolved_at DATETIME, reopen_reason TEXT, source_module TEXT, source_record_id TEXT, version INTEGER DEFAULT 1, code TEXT, legacy_code TEXT, team_code TEXT,
    FOREIGN KEY (machine_id) REFERENCES machines(id),
    FOREIGN KEY (reported_by_id) REFERENCES users(id),
    FOREIGN KEY (assigned_to_id) REFERENCES users(id),
    FOREIGN KEY (category_id) REFERENCES incident_categories(id),
    FOREIGN KEY (branch_id) REFERENCES branches(id)
);
CREATE TABLE maintenance_performance_logs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    mechanic_id INTEGER NOT NULL,
    log_date TEXT NOT NULL,
    tickets_resolved INTEGER DEFAULT 0,
    avg_resolution_mins REAL DEFAULT 0.0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (mechanic_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE documents_templates (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    description TEXT,
    doc_type TEXT NOT NULL, -- LEAVE, PROPOSAL, QC_REPORT, MAINTENANCE_REQ, OTHER
    department_id INTEGER,
    file_r2_key TEXT NOT NULL,
    file_type TEXT NOT NULL, -- docx, pdf
    placeholders_json TEXT NOT NULL, -- JSON array of detected placeholder keys & form schema
    created_by_id INTEGER NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (department_id) REFERENCES departments(id),
    FOREIGN KEY (created_by_id) REFERENCES users(id)
);
CREATE TABLE documents_generated (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    template_id INTEGER NOT NULL,
    title TEXT NOT NULL,
    creator_id INTEGER NOT NULL,
    department_id INTEGER,
    form_data_json TEXT NOT NULL,
    file_r2_key TEXT NOT NULL,
    status TEXT DEFAULT 'PENDING', -- PENDING, APPROVED, REJECTED
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (template_id) REFERENCES documents_templates(id),
    FOREIGN KEY (creator_id) REFERENCES users(id),
    FOREIGN KEY (department_id) REFERENCES departments(id)
);
CREATE TABLE document_approval_flow (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    document_id INTEGER NOT NULL,
    step_order INTEGER NOT NULL,
    approver_role_id INTEGER,
    approver_id INTEGER,
    status TEXT DEFAULT 'PENDING', -- PENDING, APPROVED, REJECTED
    comments TEXT,
    actioned_at DATETIME,
    FOREIGN KEY (document_id) REFERENCES documents_generated(id) ON DELETE CASCADE,
    FOREIGN KEY (approver_role_id) REFERENCES roles(id),
    FOREIGN KEY (approver_id) REFERENCES users(id)
);
CREATE TABLE jobs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    description TEXT NOT NULL,
    requirements TEXT NOT NULL,
    location TEXT DEFAULT 'Văn Phòng Chuỗi SKECHERS',
    department_id INTEGER,
    status TEXT DEFAULT 'ACTIVE', -- ACTIVE, CLOSED
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP, version INTEGER DEFAULT 1,
    FOREIGN KEY (department_id) REFERENCES departments(id)
);
CREATE TABLE job_applications (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    job_id INTEGER NOT NULL,
    candidate_name TEXT NOT NULL,
    candidate_email TEXT NOT NULL,
    candidate_phone TEXT NOT NULL,
    cv_r2_key TEXT,
    cover_letter TEXT,
    status TEXT DEFAULT 'SUBMITTED', -- SUBMITTED, REVIEWING, ACCEPTED, REJECTED
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP, version INTEGER DEFAULT 1,
    FOREIGN KEY (job_id) REFERENCES jobs(id) ON DELETE CASCADE
);
CREATE TABLE notifications (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    title TEXT NOT NULL,
    message TEXT NOT NULL,
    type TEXT DEFAULT 'INFO',
    is_read INTEGER DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP, module TEXT, record_id TEXT,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE audit_logs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER,
    action TEXT NOT NULL,
    target_entity TEXT,
    details TEXT,
    ip_address TEXT,
    timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, changes_json TEXT, user_agent TEXT, data_before TEXT, data_after TEXT, emp_code TEXT, role_code TEXT, module TEXT DEFAULT 'SYSTEM', record_id TEXT, emp_name TEXT);
CREATE TABLE users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    emp_code TEXT NOT NULL UNIQUE,
    email TEXT UNIQUE,
    name TEXT NOT NULL,
    phone TEXT,
    password_hash TEXT NOT NULL DEFAULT '123456',
    role_id INTEGER DEFAULT 5,
    department_id INTEGER DEFAULT 1,
    title TEXT,
    department TEXT,
    role_code TEXT,
    status TEXT DEFAULT 'ACTIVE',
    avatar_url TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
, version INTEGER DEFAULT 1, ngay_vao TEXT, vtcv_hien_tai TEXT, vtcv_sap TEXT, vtcv_sap_xep TEXT, bo_phan_moi TEXT, phong_ban_hien_tai TEXT, pb_sap_xep TEXT, factory_id TEXT, workshop_id TEXT, line_id TEXT, chuyen_id TEXT, to_id TEXT, vtcv TEXT, phong_ban_moi TEXT, ghi_chu TEXT);
CREATE TABLE user_profile (
    id TEXT PRIMARY KEY,
    emp_code TEXT,
    name TEXT NOT NULL,
    email TEXT,
    phone TEXT,
    avatar TEXT,
    title TEXT,
    department TEXT,
    role_code TEXT,
    redirect_url TEXT,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
, version INTEGER DEFAULT 1);
CREATE TABLE idempotency_logs (
    key TEXT PRIMARY KEY,
    endpoint TEXT NOT NULL,
    response_json TEXT NOT NULL,
    status_code INTEGER DEFAULT 200,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE qc_defect_reports (
    id TEXT PRIMARY KEY,
    status TEXT DEFAULT 'REPORTED', -- REPORTED, INVESTIGATING, ACTION_REQUIRED, RESOLVED, VERIFIED
    created_by TEXT NOT NULL,
    description TEXT NOT NULL,
    action_required_note TEXT,
    resolved_at DATETIME,
    verified_by TEXT,
    verified_at DATETIME,
    version INTEGER DEFAULT 1,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
, code TEXT, legacy_code TEXT, team_code TEXT);
CREATE TABLE qc_kaizen_submissions (
    id TEXT PRIMARY KEY,
    status TEXT DEFAULT 'SUBMITTED', -- SUBMITTED, UNDER_REVIEW, APPROVED, REJECTED, IMPLEMENTED
    submitted_by TEXT NOT NULL,
    description TEXT NOT NULL,
    review_note TEXT,
    reviewed_by TEXT,
    reviewed_at DATETIME,
    implemented_at DATETIME,
    version INTEGER DEFAULT 1,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE finance_advances (
    id TEXT PRIMARY KEY,
    emp_code TEXT NOT NULL,
    amount REAL NOT NULL,
    purpose TEXT,
    status TEXT DEFAULT 'DRAFT', -- DRAFT, PENDING_L1, PENDING_L2, APPROVED, REJECTED
    approved_level TEXT,
    l1_approved_by TEXT,
    l1_approved_at DATETIME,
    l2_approved_by TEXT,
    l2_approved_at DATETIME,
    rejection_reason TEXT,
    version INTEGER DEFAULT 1,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
, code TEXT, legacy_code TEXT);
CREATE TABLE approval_thresholds (
    module TEXT PRIMARY KEY,
    threshold_amount REAL DEFAULT 5000000.0,
    updated_by TEXT,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE ci_kaizen_proposals (
    id TEXT PRIMARY KEY,
    code TEXT NOT NULL UNIQUE,
    title TEXT NOT NULL,
    category TEXT NOT NULL, -- PRODUCTIVITY, COST_SAVING, SAFETY, AUTOMATION, 5S, MATERIAL_SAVING, EQUIPMENT, OTHER
    category_label TEXT NOT NULL, -- 3.Tăng Năng suất, 1.Tiết kiệm Vật tư, 4.An toàn lao động, etc.
    registration_type TEXT DEFAULT 'THI_DUA', -- THI_DUA, LUU_TRU
    sub_status TEXT DEFAULT 'CHO_DANH_GIA', -- DA_DANH_GIA, CHO_DANH_GIA
    region TEXT NOT NULL, -- LONG XUYÊN, ĐẾ, ĐÀ NẴNG, HỘI AN, ĐỒNG XOÀI...
    department TEXT NOT NULL,
    factory TEXT,
    proposer_name TEXT NOT NULL,
    proposer_emp_code TEXT NOT NULL,
    dept_code TEXT DEFAULT 'SK', -- DP, SK, RB, WR, Khác
    before_description TEXT,
    after_solution TEXT,
    saved_seconds INTEGER DEFAULT 0,
    before_image_url TEXT,
    after_image_url TEXT,
    attachments_json TEXT,
    status TEXT DEFAULT 'SUBMITTED', -- SUBMITTED, UNDER_REVIEW, APPROVED, REJECTED, IMPLEMENTED
    award_title TEXT, -- Giải Nhất, Giải Nhì, Giải Ba, Giải Khuyến Khích
    score_points REAL DEFAULT 0.0,
    avg_rating REAL DEFAULT 0.0,
    rating_count INTEGER DEFAULT 0,
    vote_count INTEGER DEFAULT 0,
    view_count INTEGER DEFAULT 0,
    rejection_reason TEXT,
    version INTEGER DEFAULT 1,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
, required_reviewer_ids_json TEXT, average_score REAL, evaluated_at DATETIME, comments TEXT, review_comment TEXT, proposer_position TEXT, proposer_month INTEGER, proposer_year INTEGER, hr_suggestor TEXT, customer TEXT, product_group TEXT, product_code TEXT, quantity INTEGER, pricing_direction TEXT, time_before_seconds INTEGER, time_after_seconds INTEGER, efficiency_value_vnd INTEGER, legacy_code TEXT, team_code TEXT, plant_code TEXT DEFAULT 'VP2_SKECHERS', approval_status TEXT DEFAULT 'PENDING', evaluation_result TEXT DEFAULT 'PENDING', approved_by TEXT, approved_at TEXT, evaluated_by TEXT, review_status TEXT DEFAULT 'CHO_PHE_DUYET', is_archived INTEGER DEFAULT 0, before_video_url TEXT, after_video_url TEXT, pair_quantity INTEGER DEFAULT 0, line TEXT, total_savings_vnd INTEGER DEFAULT 0, total_savings_words TEXT, trang_thai TEXT DEFAULT 'CHO_DUYET', source_region TEXT DEFAULT 'Văn phòng Chuỗi', site_code TEXT DEFAULT 'vpchuoiskechers', external_id TEXT, plant_group TEXT DEFAULT 'VPCHUOI', is_edited INTEGER DEFAULT 0, so_giay_tiet_kiem REAL DEFAULT 0, cost_before REAL DEFAULT 0, cost_after REAL DEFAULT 0);
CREATE TABLE ci_kaizen_evaluations (
    id TEXT PRIMARY KEY,
    proposal_id TEXT NOT NULL,
    evaluator_emp_code TEXT NOT NULL,
    evaluator_name TEXT NOT NULL,
    rating_stars INTEGER CHECK (rating_stars BETWEEN 1 AND 5),
    score_given REAL,
    comments TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (proposal_id) REFERENCES ci_kaizen_proposals(id) ON DELETE CASCADE
);
CREATE TABLE ci_kaizen_votes (
    id TEXT PRIMARY KEY,
    proposal_id TEXT NOT NULL,
    user_emp_code TEXT NOT NULL,
    voted_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(proposal_id, user_emp_code)
);
CREATE TABLE idempotency_keys (
              key TEXT PRIMARY KEY,
              status_code INTEGER DEFAULT 200,
              response_body TEXT NOT NULL,
              created_at DATETIME DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE push_subscriptions (
    id TEXT PRIMARY KEY,
    emp_code TEXT NOT NULL,
    endpoint TEXT NOT NULL UNIQUE,
    p256dh TEXT NOT NULL,
    auth TEXT NOT NULL,
    user_agent TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE rate_limiters (
    key TEXT PRIMARY KEY,
    request_count INTEGER DEFAULT 1,
    window_start DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE record_counters (
          scope_key TEXT PRIMARY KEY,
          last_seq INTEGER DEFAULT 0,
          updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
      );
CREATE TABLE system_settings (
              key TEXT PRIMARY KEY,
              value TEXT,
              updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE ci_kaizen_status_history (
              id INTEGER PRIMARY KEY AUTOINCREMENT,
              proposal_id TEXT NOT NULL,
              from_status TEXT,
              to_status TEXT NOT NULL,
              action TEXT NOT NULL,
              actor_id TEXT,
              actor_name TEXT,
              note TEXT,
              created_at DATETIME DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE regional_kpi_targets (
              id TEXT PRIMARY KEY,
              plant_code TEXT DEFAULT 'VP2_SKECHERS',
              department_name TEXT NOT NULL UNIQUE,
              monthly_target INTEGER NOT NULL DEFAULT 10,
              created_at DATETIME DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE ci_kaizen_assignments (
              id TEXT PRIMARY KEY,
              proposal_id TEXT NOT NULL,
              judge_emp_code TEXT NOT NULL,
              judge_name TEXT,
              judge_title TEXT,
              assigned_by_emp_code TEXT,
              status TEXT DEFAULT 'PENDING',
              assigned_at DATETIME DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE ci_kaizen_expert_evaluations (
              id TEXT PRIMARY KEY,
              proposal_id TEXT NOT NULL,
              evaluator_emp_code TEXT NOT NULL,
              evaluator_name TEXT NOT NULL,
              evaluator_title TEXT,
              prerequisite_pass INTEGER DEFAULT 1,
              criterion1_score REAL DEFAULT 0,
              criterion2_score REAL DEFAULT 0,
              criterion3_score REAL DEFAULT 0,
              criterion4_score REAL DEFAULT 0,
              criterion5_score REAL DEFAULT 0,
              total_score REAL DEFAULT 0,
              comments TEXT,
              status TEXT DEFAULT 'DRAFT',
              confirmed_at DATETIME,
              created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
              updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
              FOREIGN KEY (proposal_id) REFERENCES ci_kaizen_proposals(id) ON DELETE CASCADE
            );
CREATE TABLE hr_employees (
                id TEXT PRIMARY KEY, name TEXT NOT NULL, title TEXT NOT NULL, department TEXT NOT NULL,
                branch TEXT DEFAULT 'Văn Phòng Chuỗi SKECHERS HQ', email TEXT, phone TEXT,
                status TEXT DEFAULT 'Active', contract_type TEXT DEFAULT 'Chính thức (2 năm)', join_date TEXT,
                probation_end_date TEXT, contract_end_date TEXT, avatar TEXT DEFAULT '/images/tbs-logo.png',
                salary_base TEXT, performance_score TEXT DEFAULT 'A', is_high_performer INTEGER DEFAULT 0,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE landing_cms (
                id TEXT PRIMARY KEY,
                config_json TEXT NOT NULL,
                updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
              );
CREATE TABLE token_blacklist (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    token_hash TEXT NOT NULL UNIQUE,
    emp_code TEXT NOT NULL,
    expires_at DATETIME NOT NULL,
    blacklisted_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    reason TEXT DEFAULT 'LOGOUT'
);
CREATE TABLE kaizen_proposals (
              id TEXT PRIMARY KEY,
              code TEXT UNIQUE,
              title TEXT NOT NULL,
              category TEXT DEFAULT 'PRODUCTIVITY',
              category_label TEXT DEFAULT '3.Tăng Năng suất',
              registration_type TEXT DEFAULT 'THI_DUA',
              region TEXT DEFAULT 'VP CHUỖI',
              department TEXT,
              factory TEXT DEFAULT 'VP CHUỖI',
              line TEXT,
              proposer_name TEXT,
              proposer_emp_code TEXT,
              before_description TEXT,
              after_solution TEXT,
              saved_seconds INTEGER DEFAULT 0,
              so_giay_tiet_kiem INTEGER DEFAULT 0,
              diem_hieu_qua REAL DEFAULT 0.0,
              diem_tong_hop REAL DEFAULT 0.0,
              hang_xep INTEGER DEFAULT 0,
              before_image_url TEXT,
              after_image_url TEXT,
              attachments_json TEXT,
              status TEXT DEFAULT 'SUBMITTED',
              sub_status TEXT DEFAULT 'CHO_DUYET',
              trang_thai TEXT DEFAULT 'CHO_DUYET',
              review_status TEXT DEFAULT 'CHO_DUYET',
              created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
              updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE gemba_factories (
    id TEXT PRIMARY KEY,
    code TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL,
    sort_order INTEGER DEFAULT 1,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE gemba_workshops (
    id TEXT PRIMARY KEY,
    factory_id TEXT NOT NULL,
    code TEXT NOT NULL,
    name TEXT NOT NULL,
    sort_order INTEGER DEFAULT 1,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (factory_id) REFERENCES gemba_factories(id) ON DELETE CASCADE
);
CREATE TABLE gemba_lines (
    id TEXT PRIMARY KEY,
    workshop_id TEXT NOT NULL,
    code TEXT NOT NULL,
    name TEXT NOT NULL,
    sort_order INTEGER DEFAULT 1,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (workshop_id) REFERENCES gemba_workshops(id) ON DELETE CASCADE
);
CREATE TABLE gemba_teams (
    id TEXT PRIMARY KEY,
    line_id TEXT NOT NULL,
    code TEXT NOT NULL,
    name TEXT NOT NULL,
    sort_order INTEGER DEFAULT 1,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (line_id) REFERENCES gemba_lines(id) ON DELETE CASCADE
);
CREATE TABLE gemba_categories (
    id TEXT PRIMARY KEY,
    code TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL,
    sort_order INTEGER DEFAULT 1,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE gemba_sequences (
    year INTEGER PRIMARY KEY,
    last_number INTEGER DEFAULT 0,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE gemba_records (
    id TEXT PRIMARY KEY,
    code TEXT NOT NULL UNIQUE,
    title TEXT NOT NULL,
    description TEXT,
    category_id TEXT NOT NULL,
    priority TEXT DEFAULT 'TRUNG_BINH', -- CAO, TRUNG_BINH, THAP
    status TEXT DEFAULT 'NEW', -- NEW, PROCESSING, COMPLETED (Note: Overdue is computed dynamically)
    factory_id TEXT NOT NULL,
    workshop_id TEXT NOT NULL,
    line_id TEXT NOT NULL,
    team_id TEXT NOT NULL,
    created_by_emp_code TEXT NOT NULL,
    created_by_name TEXT,
    assigned_to_emp_code TEXT,
    assigned_to_name TEXT,
    assigned_group TEXT,
    due_at DATETIME,
    closed_at DATETIME,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (category_id) REFERENCES gemba_categories(id),
    FOREIGN KEY (factory_id) REFERENCES gemba_factories(id),
    FOREIGN KEY (workshop_id) REFERENCES gemba_workshops(id),
    FOREIGN KEY (line_id) REFERENCES gemba_lines(id),
    FOREIGN KEY (team_id) REFERENCES gemba_teams(id)
);
CREATE TABLE gemba_user_scopes (
    id TEXT PRIMARY KEY,
    emp_code TEXT NOT NULL,
    factory_id TEXT,
    workshop_id TEXT,
    line_id TEXT,
    team_id TEXT,
    gemba_role TEXT NOT NULL DEFAULT 'OPERATOR', -- ADMIN, GĐ_NHÀ_MÁY, CN_CI_KHU_VỰC, QLCL_KHU_VỰC, MMTB_KHU_VỰC, ĐỐC_CÔNG, QLCL_PX, TRƯỞNG_LINE, TỔ_TRƯỞNG, OPERATOR
    mmtb_token TEXT,
    status TEXT DEFAULT 'ACTIVE',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (emp_code) REFERENCES users(emp_code) ON DELETE CASCADE
);
CREATE TABLE gemba_history (
    id TEXT PRIMARY KEY,
    record_id TEXT NOT NULL,
    action_type TEXT NOT NULL, -- CREATE, UPDATE_STATUS, REASSIGN, ADD_NOTE, CLOSE
    old_status TEXT,
    new_status TEXT,
    note TEXT,
    performed_by TEXT NOT NULL,
    performed_by_name TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (record_id) REFERENCES gemba_records(id) ON DELETE CASCADE
);
CREATE TABLE gemba_attachments (
    id TEXT PRIMARY KEY,
    record_id TEXT NOT NULL,
    r2_object_key TEXT NOT NULL,
    url TEXT NOT NULL,
    file_type TEXT DEFAULT 'image/jpeg',
    file_size INTEGER DEFAULT 0,
    uploaded_by TEXT NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (record_id) REFERENCES gemba_records(id) ON DELETE CASCADE
);
CREATE TABLE ci_kaizen_rate_limits (
            id TEXT PRIMARY KEY,
            ip_emp_key TEXT NOT NULL,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP
          );
CREATE TABLE ci_kaizen_merged_proposals (
                id TEXT PRIMARY KEY,
                original_proposal_id TEXT,
                merged_proposal_id TEXT,
                attachments_json TEXT,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP
              );
CREATE TABLE system_backups (
            id TEXT PRIMARY KEY,
            backup_type TEXT NOT NULL,
            file_name TEXT NOT NULL,
            file_size_bytes INTEGER DEFAULT 0,
            gdrive_file_id TEXT,
            status TEXT DEFAULT 'SUCCESS',
            error_message TEXT,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP
          );
CREATE TABLE ci_kaizen_sync_logs (
                id TEXT PRIMARY KEY, source_site TEXT NOT NULL, status TEXT NOT NULL, synced_count INTEGER DEFAULT 0, created_count INTEGER DEFAULT 0,
                updated_count INTEGER DEFAULT 0, skipped_count INTEGER DEFAULT 0, message TEXT, error_detail TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
              );
CREATE TABLE role_workspace_config (
  id TEXT PRIMARY KEY,
  role TEXT NOT NULL,
  route TEXT NOT NULL,
  label TEXT NOT NULL,
  icon TEXT,
  sort_order INTEGER DEFAULT 0,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE department_kpi_monthly (
  id TEXT PRIMARY KEY,
  department_id TEXT NOT NULL,
  year INTEGER NOT NULL,
  month INTEGER NOT NULL,
  kpi_name TEXT NOT NULL,
  target_value REAL,
  actual_value REAL,
  unit TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE task_boards (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  type TEXT NOT NULL,
  department_id TEXT,
  owner_id TEXT NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE task_lists (
  id TEXT PRIMARY KEY,
  board_id TEXT NOT NULL,
  name TEXT NOT NULL,
  sort_order INTEGER DEFAULT 0,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE task_cards (
  id TEXT PRIMARY KEY,
  list_id TEXT NOT NULL,
  board_id TEXT NOT NULL,
  title TEXT NOT NULL,
  description TEXT,
  assignee_id TEXT,
  deadline DATETIME,
  status TEXT DEFAULT 'in_progress',
  color_state TEXT DEFAULT 'green',
  job_position_id TEXT,
  sort_order INTEGER DEFAULT 0,
  created_by TEXT NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE task_card_checklist_items (
  id TEXT PRIMARY KEY,
  card_id TEXT NOT NULL,
  content TEXT NOT NULL,
  is_done INTEGER DEFAULT 0,
  sort_order INTEGER DEFAULT 0
);
CREATE TABLE task_card_attachments (
  id TEXT PRIMARY KEY,
  card_id TEXT NOT NULL,
  file_type TEXT NOT NULL,
  storage_key TEXT NOT NULL,
  uploaded_by TEXT NOT NULL,
  uploaded_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE task_card_reviews (
  id TEXT PRIMARY KEY,
  card_id TEXT NOT NULL,
  reviewer_id TEXT NOT NULL,
  rating INTEGER,
  comment TEXT,
  reviewed_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE task_notifications_sent (
  id TEXT PRIMARY KEY,
  card_id TEXT NOT NULL,
  notify_date DATE NOT NULL,
  sent_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(card_id, notify_date)
);
CREATE TABLE job_position_templates (
  id TEXT PRIMARY KEY,
  position_name TEXT NOT NULL,
  department_id TEXT,
  checklist_template TEXT
);
CREATE TABLE auth_login_history (
  id TEXT PRIMARY KEY,
  user_id TEXT,
  emp_code TEXT,
  ip TEXT,
  user_agent TEXT,
  success INTEGER DEFAULT 1,
  failure_reason TEXT,
  timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE account_change_history (
  id TEXT PRIMARY KEY,
  target_user_id TEXT NOT NULL,
  field_changed TEXT NOT NULL,
  old_value TEXT,
  new_value TEXT,
  changed_by TEXT NOT NULL,
  timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE credential_change_history (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  changed_by TEXT NOT NULL,
  change_type TEXT NOT NULL,
  timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE document_snapshots (
  id TEXT PRIMARY KEY,
  document_id TEXT NOT NULL,
  storage_path TEXT NOT NULL,
  version INTEGER DEFAULT 1,
  snapshot_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE incremental_backup_state (
  table_name TEXT PRIMARY KEY,
  last_synced_at DATETIME,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE admin_module_pin (
  user_id TEXT PRIMARY KEY,
  pin_hash TEXT NOT NULL,
  must_change_pin INTEGER DEFAULT 1,
  failed_attempts INTEGER DEFAULT 0,
  locked_until DATETIME,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE module_152_access_log (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  success INTEGER NOT NULL,
  ip TEXT,
  user_agent TEXT,
  accessed_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE admin_alert_recipients (
  id TEXT PRIMARY KEY,
  user_id TEXT,
  email TEXT NOT NULL,
  role TEXT,
  is_active INTEGER DEFAULT 1,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE user_security_pin (
  user_id TEXT PRIMARY KEY,
  pin_hash TEXT NOT NULL,
  must_change_pin INTEGER DEFAULT 1,
  failed_attempts INTEGER DEFAULT 0,
  locked_until TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE projects (
  id TEXT PRIMARY KEY,
  code TEXT UNIQUE NOT NULL,
  title TEXT NOT NULL,
  description TEXT,
  department_id TEXT,
  manager_id TEXT NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE project_members (
  project_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  project_role TEXT CHECK(project_role IN ('MANAGER', 'MEMBER', 'VIEWER')) DEFAULT 'MEMBER',
  PRIMARY KEY (project_id, user_id),
  FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE
);
CREATE TABLE board_members (
  board_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  board_role TEXT CHECK(board_role IN ('OWNER', 'EDITOR', 'VIEWER')) DEFAULT 'EDITOR',
  PRIMARY KEY (board_id, user_id),
  FOREIGN KEY (board_id) REFERENCES task_boards(id) ON DELETE CASCADE
);
CREATE TABLE task_board_columns (
  id TEXT PRIMARY KEY,
  board_id TEXT NOT NULL,
  title TEXT NOT NULL,
  semantic_type TEXT NOT NULL CHECK(semantic_type IN ('TODO', 'IN_PROGRESS', 'REVIEW', 'DONE', 'CUSTOM')),
  position REAL NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (board_id) REFERENCES task_boards(id) ON DELETE CASCADE
);
CREATE TABLE tasks (
  id TEXT PRIMARY KEY,
  task_code TEXT UNIQUE NOT NULL,
  title TEXT NOT NULL,
  description TEXT,
  board_id TEXT NOT NULL,
  column_id TEXT NOT NULL,
  position REAL NOT NULL,
  department_id TEXT,
  project_id TEXT,
  creator_id TEXT NOT NULL,
  assignee_id TEXT,
  reviewer_id TEXT,
  priority TEXT CHECK(priority IN ('LOW', 'MEDIUM', 'HIGH', 'URGENT')) DEFAULT 'MEDIUM',
  status TEXT NOT NULL DEFAULT 'TODO',
  progress INTEGER DEFAULT 0,
  requires_review INTEGER DEFAULT 1,
  start_date TEXT,
  due_date TEXT,
  result_description TEXT,
  version INTEGER DEFAULT 1,
  completed_at DATETIME,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE task_members (
  task_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  role_type TEXT CHECK(role_type IN ('ASSIGNEE', 'COLLABORATOR')) DEFAULT 'COLLABORATOR',
  PRIMARY KEY (task_id, user_id),
  FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE
);
CREATE TABLE task_labels (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  color_code TEXT NOT NULL,
  department_id TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE task_label_links (
  task_id TEXT NOT NULL,
  label_id TEXT NOT NULL,
  PRIMARY KEY (task_id, label_id),
  FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE,
  FOREIGN KEY (label_id) REFERENCES task_labels(id) ON DELETE CASCADE
);
CREATE TABLE task_checklists (
  id TEXT PRIMARY KEY,
  task_id TEXT NOT NULL,
  title TEXT NOT NULL,
  position REAL DEFAULT 0,
  FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE
);
CREATE TABLE task_checklist_items (
  id TEXT PRIMARY KEY,
  checklist_id TEXT NOT NULL,
  title TEXT NOT NULL,
  completed INTEGER DEFAULT 0,
  completed_by TEXT,
  completed_at TEXT,
  position REAL DEFAULT 0,
  FOREIGN KEY (checklist_id) REFERENCES task_checklists(id) ON DELETE CASCADE
);
CREATE TABLE task_comments (
  id TEXT PRIMARY KEY,
  task_id TEXT NOT NULL,
  author_id TEXT NOT NULL,
  content TEXT NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE
);
CREATE TABLE task_attachments (
  id TEXT PRIMARY KEY,
  task_id TEXT NOT NULL,
  uploader_id TEXT NOT NULL,
  file_name TEXT NOT NULL,
  file_url TEXT NOT NULL,
  file_size INTEGER DEFAULT 0,
  mime_type TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE
);
CREATE TABLE task_reviews (
  id TEXT PRIMARY KEY,
  task_id TEXT NOT NULL,
  reviewer_id TEXT NOT NULL,
  decision TEXT NOT NULL CHECK(decision IN ('APPROVE', 'REQUEST_CHANGES')),
  rating INTEGER,
  note TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE
);
CREATE TABLE task_activity_logs (
  id TEXT PRIMARY KEY,
  task_id TEXT NOT NULL,
  actor_id TEXT NOT NULL,
  action TEXT NOT NULL,
  details TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE
);
CREATE TABLE performance_weight_config (
  id TEXT PRIMARY KEY,
  completion_weight REAL DEFAULT 0.3,
  on_time_weight REAL DEFAULT 0.3,
  quality_weight REAL DEFAULT 0.2,
  checklist_weight REAL DEFAULT 0.2,
  updated_by TEXT,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE sys_users (
                  id TEXT PRIMARY KEY,
                  emp_code TEXT UNIQUE,
                  name TEXT,
                  email TEXT,
                  phone TEXT,
                  title TEXT,
                  department TEXT,
                  role_code TEXT,
                  status TEXT DEFAULT 'ACTIVE',
                  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
                , ngay_vao TEXT, vtcv_hien_tai TEXT, phong_ban_hien_tai TEXT, vtcv_sap TEXT, vtcv_sap_xep TEXT, pb_sap_xep TEXT, bo_phan_moi TEXT, phong_ban_moi TEXT, ghi_chu TEXT);
CREATE TABLE sys_my_tasks (
              id TEXT PRIMARY KEY,
              code TEXT,
              title TEXT,
              description TEXT,
              department_id TEXT,
              assignee_emp_code TEXT,
              assignee_name TEXT,
              reporter_emp_code TEXT,
              reviewer_emp_code TEXT,
              priority TEXT,
              start_date TEXT,
              due_date TEXT,
              status TEXT,
              progress INTEGER,
              tags TEXT,
              checklist TEXT,
              result_description TEXT,
              created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
              updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
            , project_id TEXT, help_reason TEXT, help_notified_to TEXT);
CREATE TABLE sys_notifications (
                id TEXT PRIMARY KEY,
                title TEXT,
                message TEXT,
                type TEXT,
                target_user TEXT,
                link TEXT,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP
              );
CREATE TABLE sys_metadata (
                  key TEXT PRIMARY KEY,
                  value TEXT
                );
CREATE TABLE pph_entries (
      id TEXT PRIMARY KEY,
      team_id TEXT NOT NULL,
      entry_date TEXT NOT NULL,
      slot TEXT NOT NULL,
      worker_count INTEGER,
      model TEXT,
      planned_qty INTEGER,
      actual_qty INTEGER,
      submitted_by TEXT,
      submitted_at TEXT NOT NULL, target_rft REAL, shortfall_cause_group TEXT, shortfall_reason TEXT, shortfall_cause_sub TEXT, shortfall_solution TEXT, error_count INTEGER, production_hours REAL,
      UNIQUE(team_id, entry_date, slot)
    );
CREATE TABLE pph_shortfall_causes (
      id TEXT PRIMARY KEY,
      parent_id TEXT,
      name TEXT NOT NULL,
      sort_order INTEGER NOT NULL DEFAULT 0
    );
CREATE TABLE pph_dashboard_lines (
