    , image_url TEXT, paused INTEGER NOT NULL DEFAULT 0);
CREATE TABLE pph_tv_media_slots (
      id TEXT PRIMARY KEY,
      media_url TEXT NOT NULL,
      media_type TEXT NOT NULL,
      start_time TEXT NOT NULL,
      end_time TEXT NOT NULL,
