          );
CREATE TABLE ci_kaizen_judge_guest_accounts (
            id TEXT PRIMARY KEY,
            round_id TEXT NOT NULL,
            full_name TEXT NOT NULL,
            organization TEXT NOT NULL,
            contact_info TEXT NOT NULL,
            username TEXT,
            one_time_passcode TEXT,
            dung_chung INTEGER DEFAULT 1,
