CREATE TABLE zalo_user_links (
  emp_code TEXT PRIMARY KEY,
  chat_id TEXT NOT NULL,
  zalo_name TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE zalo_linking_codes (
  code TEXT PRIMARY KEY,
  emp_code TEXT NOT NULL,
  expires_at DATETIME NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE zalo_notification_logs (
  id TEXT PRIMARY KEY,
  event_type TEXT NOT NULL,
  priority TEXT NOT NULL,
  recipient_emp_code TEXT,
  chat_id TEXT,
  message_text TEXT,
  status TEXT DEFAULT 'SUCCESS',
  error_detail TEXT,
  idempotency_key TEXT UNIQUE,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE zalo_config (
  id TEXT PRIMARY KEY DEFAULT 'main',
  quiet_hours_start TEXT DEFAULT '17:00',
  quiet_hours_end TEXT DEFAULT '06:30',
  meeting_reminder_mins INTEGER DEFAULT 30,
  visitor_reminder_days INTEGER DEFAULT 2,
  reception_group_chat_id TEXT,
  event_toggles_json TEXT,
  priority_config_json TEXT,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
, confirmed_group_chat_id TEXT);
CREATE TABLE zalo_captured_groups (
  group_chat_id TEXT PRIMARY KEY,
  group_name TEXT,
  last_message TEXT,
  sender_name TEXT,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE zalo_bot_chat_history (id TEXT PRIMARY KEY, chat_id TEXT, user_id TEXT, role TEXT, text TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE zalo_bot_rate_limit (user_id TEXT PRIMARY KEY, count INTEGER DEFAULT 1, reset_at DATETIME);
CREATE TABLE zalo_bot_allowed_groups (group_id TEXT PRIMARY KEY, name TEXT, is_active INTEGER DEFAULT 1, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE bot_knowledge (id TEXT PRIMARY KEY, question TEXT, answer TEXT, tags TEXT, status TEXT DEFAULT 'draft', source TEXT DEFAULT 'admin', created_by TEXT, approved_by TEXT, hit_count INTEGER DEFAULT 0, access_label TEXT DEFAULT 'internal', updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE bot_unanswered (id TEXT PRIMARY KEY, question_hash TEXT UNIQUE, question_text TEXT, count INTEGER DEFAULT 1, status TEXT DEFAULT 'new', first_seen DATETIME DEFAULT CURRENT_TIMESTAMP, last_seen DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sys_audit_logs (id TEXT PRIMARY KEY, actor_id TEXT, actor_name TEXT, action TEXT, target TEXT, details TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE zalo_processed_events (event_id TEXT PRIMARY KEY, processed_at DATETIME DEFAULT CURRENT_TIMESTAMP);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX idx_users_emp_code ON users(emp_code);
CREATE UNIQUE INDEX idx_room_booking_unique ON room_bookings(room_id, booking_date, time_slot) WHERE status != 'CANCELLED';
CREATE UNIQUE INDEX idx_room_booking_slot 
              ON room_bookings (room_id, booking_date, time_slot) 
              WHERE status != 'CANCELLED';
CREATE INDEX idx_token_blacklist_hash ON token_blacklist(token_hash);
CREATE INDEX idx_token_blacklist_expires ON token_blacklist(expires_at);
CREATE INDEX idx_gemba_records_factory_ws ON gemba_records(factory_id, workshop_id, line_id, team_id);
CREATE INDEX idx_gemba_records_status_due ON gemba_records(status, due_at);
CREATE INDEX idx_gemba_records_created ON gemba_records(created_at DESC);
CREATE INDEX idx_gemba_records_code ON gemba_records(code);
CREATE INDEX idx_gemba_user_scopes_emp ON gemba_user_scopes(emp_code);
CREATE INDEX idx_gemba_history_record ON gemba_history(record_id, created_at ASC);
CREATE INDEX idx_gemba_attachments_record ON gemba_attachments(record_id);
CREATE UNIQUE INDEX idx_push_endpoint ON push_subscriptions(endpoint);
CREATE INDEX idx_notif_user ON notifications(user_id, is_read, created_at);
CREATE INDEX idx_tasks_board ON tasks(board_id);
CREATE INDEX idx_tasks_column ON tasks(column_id);
CREATE INDEX idx_tasks_assignee ON tasks(assignee_id);
CREATE INDEX idx_tasks_dept ON tasks(department_id);
CREATE INDEX idx_task_members_task ON task_members(task_id);
CREATE INDEX idx_task_comments_task ON task_comments(task_id);
CREATE UNIQUE INDEX idx_sys_users_emp_code ON sys_users(emp_code)
              ;
CREATE INDEX idx_pph_tv_short_links_line_id ON pph_tv_short_links(line_id);
